    // SARGABLE: bare column + half-open range + sort matches ix_acct_date
    // → Index Range Scan, no separate Sort, prunes to partition if partitioned
    List<Transaction> findByAccountIdAndCreatedAtGreaterThanEqualAndCreatedAtLessThanOrderByCreatedAt(
