package com.bank.optimize.service;

import com.bank.optimize.model.Transaction;
import com.bank.optimize.repository.TransactionRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.time.LocalDateTime;
import java.util.List;

@Service
public class StatementService {
    private static final Logger log = LoggerFactory.getLogger(StatementService.class);
    private final TransactionRepository repo;

    public StatementService(TransactionRepository repo) { this.repo = repo; }

    public List<Transaction> statement(String accountId, LocalDateTime from, LocalDateTime to) {
        // Sargable range (no function on created_at) + composite index + pre-sorted
        log.info("Optimized statement: account {} range {}..{} uses ix_acct_date (no Seq Scan, no Sort)",
                 accountId, from, to);
        return repo
          .findByAccountIdAndCreatedAtGreaterThanEqualAndCreatedAtLessThanOrderByCreatedAt(
              accountId, from, to);
    }
}
